// Finite-alphabet MFSK in a 2.2 kHz band: Monte Carlo GMI of practical tone receivers.
//
// One constant-envelope tone per dwell T chosen uniformly from M = floor(B/spacing) tones.
// The whole band is represented by its orthonormal DFT bins over the dwell (bin width 1/T):
// noise bins are i.i.d. CN(0,1) (N0 = 1); the transmitted tone's fading signal is generated by
// exact spectral synthesis at a sub-band rate and added to the band bins, so leakage into
// neighbouring tones is included. Received C/N0 = P (Hz); peak = average power.
// Receivers (all evaluated on the same trials):
//   WPm   weighted periodogram with weights from the true composite spectrum (a receiver that
//         has adapted to the channel over the message);
//   GLRT  per-symbol maximum over a bank of Gaussian-spread hypotheses {0.1,0.3,1,3,10,30} Hz
//         of the normalized log-likelihood ratio (no adaptation across symbols);
//   BAND  unweighted energy in the tone's own band of width spacing over the dwell (an ideal
//         per-tone band energy detector; equal to FT8-style single-bin detection when T = 1/spacing);
//   COH   one DFT bin per tone over the whole dwell.
// Per-symbol GMI = max_s { log2 M - E log2 sum_m exp(s (L_m - L_tx)) }, ideal interleaving.
// Timing and the Doppler centre are known; ISI and acquisition are not modelled.
//
// Build: g++ -O3 -march=native -std=c++20 -fopenmp finite_alphabet_mc.cpp -o finite_alphabet_mc
// Run:   ./finite_alphabet_mc [trials] > results/finite_alphabet_mc.md
#include <cmath>
#include <complex>
#include <cstdio>
#include <cstdint>
#include <cstdlib>
#include <string>
#include <vector>
#include <algorithm>
#include <omp.h>

using cd = std::complex<double>;
static const double PI = 3.14159265358979323846;
static const double LN2 = 0.69314718055994530942;
static double db(double x) { return 10 * std::log10(x); }
static double undb(double x) { return std::pow(10.0, x / 10); }

// ---------- RNG ----------
struct Rng {
    uint64_t s[4];
    explicit Rng(uint64_t seed) {
        for (int i = 0; i < 4; ++i) { seed += 0x9E3779B97F4A7C15ull; uint64_t z = seed; z = (z ^ (z >> 30)) * 0xBF58476D1CE4E5B9ull; z = (z ^ (z >> 27)) * 0x94D049BB133111EBull; s[i] = z ^ (z >> 31); }
    }
    static uint64_t rotl(uint64_t x, int k) { return (x << k) | (x >> (64 - k)); }
    uint64_t next() { uint64_t r = rotl(s[1] * 5, 7) * 9, t = s[1] << 17; s[2] ^= s[0]; s[3] ^= s[1]; s[1] ^= s[2]; s[0] ^= s[3]; s[2] ^= t; s[3] = rotl(s[3], 45); return r; }
    double uni() { return ((next() >> 11) + 0.5) * (1.0 / 9007199254740992.0); }
    cd cn() {  // CN(0,1)
        double u = uni(), v = uni(), r = std::sqrt(-std::log(u));
        return {r * std::cos(2 * PI * v), r * std::sin(2 * PI * v)};
    }
};

// ---------- FFT ----------
static void fft(std::vector<cd>& a, bool inv) {
    size_t n = a.size();
    for (size_t i = 1, j = 0; i < n; ++i) { size_t bit = n >> 1; for (; j & bit; bit >>= 1) j ^= bit; j ^= bit; if (i < j) std::swap(a[i], a[j]); }
    for (size_t len = 2; len <= n; len <<= 1) {
        double ang = 2 * PI / len * (inv ? 1 : -1);
        cd wl = std::polar(1.0, ang);
        for (size_t i = 0; i < n; i += len) { cd w = 1; for (size_t j = 0; j < len / 2; ++j) { cd u = a[i + j], v = a[i + j + len / 2] * w; a[i + j] = u + v; a[i + j + len / 2] = u - v; w *= wl; } }
    }
}

// ---------- channel ----------
struct Comp { enum Kind { LINE, GAUSS } kind; double w, c, s; };  // s = sigma
using Chan = std::vector<Comp>;
static double extent(const Chan& ch) { double m = 0; for (auto& k : ch) m = std::max(m, std::fabs(k.c) + (k.kind == Comp::GAUSS ? 5 * k.s : 0)); return m; }
static cd rho(const Chan& ch, double tau) {
    cd r = 0;
    for (auto& k : ch) r += k.w * (k.kind == Comp::LINE ? 1.0 : std::exp(-2 * PI * PI * k.s * k.s * tau * tau)) * std::polar(1.0, 2 * PI * k.c * tau);
    return r;
}
// expected signal energy lam_k in dwell-T bins k/T, k=-K..K (exact, via windowed autocorrelation FFT)
static std::vector<double> bin_energy(const Chan& ch, double P, double T, int K) {
    double fmax = std::max(extent(ch), (K + 2) / T);
    int N = 64; while (N / T < 4 * fmax + 8 / T) N <<= 1;
    double dt = T / N; int L = 2 * N;
    std::vector<cd> c(L, 0.0);
    for (int n = -(N - 1); n <= N - 1; ++n) c[(n + L) % L] += dt * (1 - std::fabs(n * dt) / T) * rho(ch, n * dt);
    fft(c, false);
    std::vector<double> lam(2 * K + 1);
    for (int k = -K; k <= K; ++k) lam[k + K] = std::max(0.0, P * c[(2 * k + L) % L].real());
    return lam;
}
// bound P - int ln(1+P S_ac) for Gaussian/line mixtures
static double bound_rate(const Chan& ch, double P) {
    double lo = 1e300, hi = -1e300, ms = 1e300; bool any = false;
    for (auto& k : ch) if (k.kind == Comp::GAUSS) { any = true; lo = std::min(lo, k.c - 14 * k.s); hi = std::max(hi, k.c + 14 * k.s); ms = std::min(ms, k.s); }
    if (!any) return P;
    int n = (int)std::min(4e6, std::max(2e4, (hi - lo) / ms * 200)); if (n % 2) ++n;
    double h = (hi - lo) / n, sum = 0;
    for (int i = 0; i <= n; ++i) {
        double f = lo + i * h, d = 0;
        for (auto& k : ch) if (k.kind == Comp::GAUSS) d += k.w / (std::sqrt(2 * PI) * k.s) * std::exp(-0.5 * (f - k.c) * (f - k.c) / (k.s * k.s));
        sum += ((i == 0 || i == n) ? 1 : (i % 2 ? 4 : 2)) * std::log1p(P * d);
    }
    return P - sum * h / 3;
}

struct Weights { std::vector<double> q; double norm; int K; };  // q over k=-K..K, norm = sum ln(1+lam)
static Weights make_weights(const Chan& model, double P, double T, double cap_hz) {
    int K = std::max(0, (int)std::ceil(std::min(extent(model) + 3.0 / T, cap_hz) * T));
    auto lam = bin_energy(model, P, T, K);
    Weights W; W.K = K; W.q.resize(lam.size()); W.norm = 0;
    for (size_t i = 0; i < lam.size(); ++i) { W.q[i] = lam[i] / (1 + lam[i]); W.norm += std::log1p(lam[i]); }
    return W;
}

struct Config { double spacing, T; };
struct NamedChan { std::string name; Chan ch; };
static Chan G(double two_sigma, double w = 1, double c = 0) { return {{Comp::GAUSS, w, c, two_sigma / 2}}; }
static Chan operator+(Chan a, const Chan& b) { a.insert(a.end(), b.begin(), b.end()); return a; }

struct Result { double gmi[4], se[4]; };

static Result run(const Chan& ch, double P, const Config& cfg, int trials, uint64_t seed) {
    const double B = 2200;
    const int M = (int)std::floor(B / cfg.spacing + 1e-9);
    const double T = cfg.T;
    const int binsPerTone = (int)std::llround(cfg.spacing * T);
    const int Nb = M * binsPerTone;                 // band bins
    auto toneBin = [&](int m) { return m * binsPerTone + binsPerTone / 2; };
    const int m0 = M / 2;
    // receivers' weights
    Weights Wm = make_weights(ch, P, T, 1e9);
    std::vector<double> bank = {0.1, 0.3, 1, 3, 10, 30};
    std::vector<Weights> Wb;
    for (double w : bank) Wb.push_back(make_weights(G(w), P, T, 1e9));
    // signal synthesis sub-band
    double ext = extent(ch);
    int Ns = 64; while (Ns / T < std::max(8 * ext + 16 / T, 4 * cfg.spacing)) Ns <<= 1;
    double fs = Ns / T;
    double minsig = 1e300; for (auto& k : ch) if (k.kind == Comp::GAUSS) minsig = std::min(minsig, k.s);
    int Lsyn = 1; while (Lsyn < 4 * Ns || (minsig < 1e299 && fs / Lsyn > minsig / 4)) Lsyn <<= 1;
    if (Lsyn > (1 << 22)) Lsyn = 1 << 22;
    std::vector<double> spec(Lsyn, 0.0);  // discrete spectrum weights for Gaussian parts
    for (auto& k : ch) if (k.kind == Comp::GAUSS) {
        std::vector<double> tmp(Lsyn); double sum = 0;
        for (int j = 0; j < Lsyn; ++j) { int jj = j < Lsyn / 2 ? j : j - Lsyn; double f = jj * fs / Lsyn; tmp[j] = std::exp(-0.5 * (f - k.c) * (f - k.c) / (k.s * k.s)); sum += tmp[j]; }
        for (int j = 0; j < Lsyn; ++j) spec[j] += k.w * tmp[j] / sum;
    }
    for (auto& v : spec) v = std::sqrt(v);
    const int NS = 20;  // s grid
    std::vector<double> sgrid(NS);
    for (int i = 0; i < NS; ++i) sgrid[i] = 0.1 * (i + 1);  // 0.1..2.0
    int nth = omp_get_max_threads();
    std::vector<std::vector<double>> acc(nth, std::vector<double>(4 * NS, 0.0)), acc2(nth, std::vector<double>(4 * NS, 0.0));
    // Variance reduction: each trial evaluates the metric on the same noise with and without the
    // signal. Estimator = f(signal, ref m0) - f(noise, ref m0) + mean_r f(noise, ref r); the last two
    // terms have equal expectation by symmetry and the average over all references is very precise.
    // Only tones within reach of the signal's bins change when the signal is added.
    const int reachBins = Ns / 2 + 1;
    int maxK = Wm.K; for (auto& W : Wb) maxK = std::max(maxK, W.K);
    const int affect = (reachBins + maxK + binsPerTone) / binsPerTone + 1;
    #pragma omp parallel
    {
        int tid = omp_get_thread_num();
        Rng rng(seed * 1000003ull + tid * 7919ull + 17);
        std::vector<cd> Z(Nb), h(Lsyn), xs(Ns);
        std::vector<double> E(Nb), E0(Nb);
        std::vector<double> L[4], L0[4];
        for (int r = 0; r < 4; ++r) { L[r].resize(M); L0[r].resize(M); }
        auto stats = [&](const std::vector<double>& En, int m, double* out) {
            int c = toneBin(m);
            double s = 0;
            for (int k = -Wm.K; k <= Wm.K; ++k) { int b = c + k; if (b >= 0 && b < Nb) s += Wm.q[k + Wm.K] * En[b]; }
            out[0] = s;
            double best = -1e300;
            for (auto& W : Wb) {
                double v = -W.norm;
                for (int k = -W.K; k <= W.K; ++k) { int b = c + k; if (b >= 0 && b < Nb) v += W.q[k + W.K] * En[b]; }
                best = std::max(best, v);
            }
            out[1] = best;
            int base = m * binsPerTone; double e = 0;
            for (int j = 0; j < binsPerTone; ++j) e += En[base + j];
            out[2] = e;          // BAND
            out[3] = En[c];      // COH
        };
        auto logsumexp = [&](const std::vector<double>& v, double sv, double ref) {
            double mx = -1e300;
            for (int m = 0; m < M; ++m) mx = std::max(mx, sv * (v[m] - ref));
            double sum = 0;
            for (int m = 0; m < M; ++m) sum += std::exp(sv * (v[m] - ref) - mx);
            return (mx + std::log(sum)) / LN2;
        };
        #pragma omp for schedule(dynamic, 8)
        for (int t = 0; t < trials; ++t) {
            for (int i = 0; i < Nb; ++i) { Z[i] = rng.cn(); E0[i] = std::norm(Z[i]); }
            double o[4];
            for (int m = 0; m < M; ++m) { stats(E0, m, o); for (int r = 0; r < 4; ++r) L0[r][m] = L[r][m] = o[r]; }
            // fading process and signal bins
            bool anyg = false; for (auto& k : ch) if (k.kind == Comp::GAUSS) anyg = true;
            for (int j = 0; j < Lsyn; ++j) h[j] = spec[j] > 0 ? spec[j] * rng.cn() : cd(0);
            if (anyg) fft(h, true); else std::fill(h.begin(), h.end(), cd(0));
            for (auto& k : ch) if (k.kind == Comp::LINE) {
                cd a = std::sqrt(k.w) * std::polar(1.0, 2 * PI * rng.uni());
                for (int n = 0; n < Ns; ++n) h[n] += a * std::polar(1.0, 2 * PI * k.c * n / fs);
            }
            double amp = std::sqrt(P / fs);
            for (int n = 0; n < Ns; ++n) xs[n] = amp * h[n];
            fft(xs, false);
            double nrm = 1.0 / std::sqrt((double)Ns);
            int c0 = toneBin(m0);
            E = E0;
            for (int k = -Ns / 2; k < Ns / 2; ++k) { int b = c0 + k; if (b >= 0 && b < Nb) E[b] = std::norm(Z[b] + xs[(k + Ns) % Ns] * nrm); }
            for (int m = std::max(0, m0 - affect); m <= std::min(M - 1, m0 + affect); ++m) { stats(E, m, o); for (int r = 0; r < 4; ++r) L[r][m] = o[r]; }
            for (int r = 0; r < 4; ++r) {
                double mean0 = 0; for (int m = 0; m < M; ++m) mean0 += L0[r][m]; mean0 /= M;
                for (int si = 0; si < NS; ++si) {
                    double sv = sgrid[si];
                    double f1 = std::log2((double)M) - logsumexp(L[r], sv, L[r][m0]);
                    double f0 = std::log2((double)M) - logsumexp(L0[r], sv, L0[r][m0]);
                    double fbar = std::log2((double)M) - logsumexp(L0[r], sv, mean0);  // = mean over refs
                    double f = f1 - f0 + fbar;
                    acc[tid][r * NS + si] += f;
                    acc2[tid][r * NS + si] += f * f;
                }
            }
        }
    }
    Result R;
    for (int r = 0; r < 4; ++r) {
        double best = -1e300, bse = 0;
        for (int si = 0; si < NS; ++si) {
            double s1 = 0, s2 = 0;
            for (int t = 0; t < nth; ++t) { s1 += acc[t][r * NS + si]; s2 += acc2[t][r * NS + si]; }
            double mean = s1 / trials, var = s2 / trials - mean * mean;
            if (mean > best) { best = mean; bse = std::sqrt(std::max(0.0, var) / trials); }
        }
        R.gmi[r] = std::max(best, 0.0); R.se[r] = bse;
    }
    return R;
}

int main(int argc, char** argv) {
    int trials = argc > 1 ? std::atoi(argv[1]) : 4000;
    std::vector<NamedChan> chans = {
        {"Stable phase", {{Comp::LINE, 1, 0, 0}}},
        {"Gauss 0.1 Hz", G(0.1)},
        {"Gauss 1 Hz", G(1)},
        {"Gauss 10 Hz", G(10)},
        {"Gauss 30 Hz", G(30)},
        {"Rician K=1, 1 Hz", Chan{{Comp::LINE, 0.5, 0, 0}} + G(1, 0.5)},
        {"Two modes 1 Hz at ±5 Hz", G(1, 0.5, -5) + G(1, 0.5, 5)},
    };
    std::vector<double> cn0s = {-10, 0, 10};
    // dwells chosen so the per-symbol energy C/N0*T is at least about 0 dB (where finite-alphabet
    // effects matter and the Monte Carlo resolves the GMI); the wideband calculator covers the rest.
    auto dwells_for = [](double c) {
        if (c < -5) return std::vector<double>{10.24, 40.96};
        if (c < 5) return std::vector<double>{2.56, 10.24, 40.96};
        return std::vector<double>{0.16, 0.64, 2.56, 10.24};
    };
    std::vector<double> spacings = {6.25, 25, 100, 200};
    const char* only = argc > 2 ? argv[2] : nullptr;   // optional channel-name filter
    double only_c = argc > 3 ? std::atof(argv[3]) : 1e9; // optional single C/N0
    printf("# Finite-alphabet MFSK in a 2.2 kHz band: receiver GMI versus the bound\n\n");
    printf("Generated by `finite_alphabet_mc.cpp` with %d trials per point (ideal interleaving, known timing and\n", trials);
    printf("Doppler centre). Entries: extra Eb/N0 relative to the peak-limited bound at the same C/N0,\n");
    printf("10·log10(R_bound/R). `±` is about two standard errors of that gap. `cap` marks rates limited by\n");
    printf("log2(M)/T (the receiver's GMI is within 10%% of log2 M bits per symbol). WPm adapts to the\n");
    printf("channel; GLRT tests six spread hypotheses per symbol; BAND is unweighted energy in each tone's own\n");
    printf("band (FT8-style single bin when T = 1/spacing); COH is one bin over the dwell.\n\n");
    for (double c : cn0s) {
        if (only_c < 1e8 && std::fabs(c - only_c) > 1e-9) continue;
        double P = undb(c);
        std::vector<Config> cfgs;
        for (double sp : spacings) for (double T : dwells_for(c)) cfgs.push_back({sp, T});
        printf("## C/N0 = %+.0f dB-Hz\n\n", c);
        printf("| Channel | bound Eb/N0 | spacing / dwell (M) | WPm | GLRT | BAND | COH |\n|---|---:|---|---:|---:|---:|---:|\n");
        for (auto& nc : chans) {
            if (only && nc.name.find(only) == std::string::npos) continue;
            double Rb = bound_rate(nc.ch, P) / LN2;
            for (auto& cf : cfgs) {
                int M = (int)std::floor(2200 / cf.spacing + 1e-9);
                Result R = run(nc.ch, P, cf, trials, (uint64_t)(1000 + c * 7 + cf.spacing * 13 + cf.T * 101));
                printf("| %s | %.2f | %g Hz / %g s (%d) |", nc.name.c_str(), db(P / Rb), cf.spacing, cf.T, M);
                for (int r = 0; r < 4; ++r) {
                    double rate = R.gmi[r] / cf.T;
                    if (R.gmi[r] <= 2 * R.se[r]) { printf(" n/s |"); continue; }
                    double gap = db(Rb / rate);
                    double gse = db(R.gmi[r] / std::max(1e-12, R.gmi[r] - 2 * R.se[r]));
                    bool cap = R.gmi[r] > 0.9 * std::log2((double)M);
                    printf(" %.2f ±%.2f%s |", gap, gse, cap ? " cap" : "");
                }
                printf("\n");
                fflush(stdout);
            }
        }
        printf("\n");
    }
    return 0;
}
